-- ============================================================
-- Миграция 06: полная загрузка кабельных журналов (КЖ) всех разделов
--
-- Что было не так: обозначение кабеля в таблице cables уникально в пределах раздела,
-- поэтому при первой загрузке молча отброшены:
--   • участки-продолжения «- // -» и «- // - // -» (шлейфы датчиков СКЗ/СО, HMI, КГПп);
--   • кабели с повторяющимся в проекте обозначением (например, ПВ2-2 на М1 и на М2);
--   • в АОВ-К00 целиком система ШВ-П.УК.С3 (10 кабелей).
-- Было 1965 строк, после миграции будет 2073 — ровно как в КЖ.
--
-- Как обозначены добавленные строки:
--   «- // -»          → «<обозначение предыдущего кабеля> (уч.N)» — N-й участок той же линии;
--   повтор обозначения → «<обозначение> (повтор 2)» — ошибка нумерации в проекте.
-- Существующие кабели и история прокладки не меняются (кроме переименования единственной
-- старой строки «- // -» в разделе в её правильное обозначение «… (уч.2)»).
-- Выполнить ОДИН раз: Supabase → SQL Editor → New query → Run
-- ============================================================

-- 1) старые строки «- // -» → правильное обозначение участка
update cables set tag = 'СО1-1 (уч.2)' where section = 'АОВ-К00' and tag = '- // -';
update cables set tag = 'HMI.C1-1 (уч.2)' where section = 'АОВ-К00' and tag = '- // - // -';
update cables set tag = 'К-1.2 (уч.2)' where section = 'АОВ-D' and tag = '- // -';
update cables set tag = 'К-1.1 (уч.2)' where section = 'АОВ-C1' and tag = '- // -';
update cables set tag = 'К-1.1 (уч.2)' where section = 'АОВ-C2' and tag = '- // -';
update cables set tag = 'К-1.1 (уч.2)' where section = 'АОВ-C3' and tag = '- // -';

-- 2) добавить всё недостающее
on conflict (section, tag) do nothing;

-- 3) итог по разделам — сверить с листом «ИТОГ» каждого КЖ
select section, count(*) as кабелей, sum(length) as метров from cables group by section order by section;
